def estimate_tokens(self, text: str) -> int:
    # byte-level BPE never emits more tokens than UTF-8 bytes: an upper bound the hard caps can trust
    return max(1, len(text.encode("utf-8")))

async def _embed_or_split(provider, batch, timeout):
    """Vectors for *batch*; a deterministic refusal is bisected down to single rows, which come back as failures."""
    try:
        return await _embed_with_retry(provider, [truncated_for(r.content, provider) for r in batch], timeout), []
    except Exception as exc:
        if _transient(exc) or len(batch) == 1:
            if len(batch) == 1 and not _transient(exc):
                return None, [(batch[0].id, exc)]
            raise
        mid = len(batch) // 2
        left, lf = await _embed_or_split(provider, batch[:mid], timeout)
        right, rf = await _embed_or_split(provider, batch[mid:], timeout)
        return _merge(left, right), lf + rf
